definition.script:
import groovy.json.JsonSlurper;

@NonCPS
def parseBuildHashes(String text) {
    def spec = new JsonSlurper().parseText(text)
    def result = [:]
    for (build in spec.application) {
        result[build.project_job_git_key.toString()] = build.git_hash?.toString()
    }
    return result
}

@NonCPS
def parseInfrastructureGitHash(String text) {
    return new JsonSlurper().parseText(text).infrastructure_git_hash?.toString()
}
def bdc_ui_docker_tag;

def retrieveBuildSpecId;
def bdcUIBuildSpecId;
def overrideUiBuildSpec;
def pipelineBuildId;
def build_hashes = [:];
def hasOverrideUI;
def infrastructure_git_hash;
def targetStack;
pipeline {
    agent any
    parameters {
        choice(name: 'TARGET_STACK', choices: ['staging','live'], description: 'Based on selection we determine if is a or b stack.')
        string(name: 'git_hash', defaultValue: '', description: 'Leave empty to use Build Spec')
        string(name: 'DATASET_S3_OBJECT_KEY', defaultValue: '', description: '')
        string(name: 'STACK_S3_BUCKET', defaultValue: '', description: '')
        booleanParam(name: 'RUN_DATABASE_MIGRATIONS', defaultValue: true, description: 'Run database migrations')
        booleanParam(name: 'DEPLOY_GATEWAY', defaultValue: true, description: 'Build and deploy pic-sure-gateway')
        booleanParam(name: 'DEPLOY_OPERATIONS', defaultValue: true, description: 'Build and deploy pic-sure-operations-service')
        booleanParam(name: 'DEPLOY_QUERY', defaultValue: true, description: 'Build and deploy pic-sure-hpds-query-service')
    }

    environment {
        SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
    }

    stages {
        stage('Retrieve Stack') {
            steps {
                script {
                    targetStack = sh(script: """
                    bash -c '
                    set +x

                    if [ ! -d "$SOURCE_SCRIPTS_FOLDER" ]; then
                        echo "Error: Source folder does not exist: $SOURCE_SCRIPTS_FOLDER"
                        exit 1
                    fi

                    for script_file in "$SOURCE_SCRIPTS_FOLDER"*.sh; do
                        chmod +x "\$script_file"
                        if [ -f "\$script_file" ] && [ -x "\$script_file" ]; then
                            . "\$script_file"  # Use dot (.) instead of `source`
                        fi
                    done

                    # The PIC-SURE Pipeline is always used to deploy to staging.
                    get_stack \"${TARGET_STACK}\"
                    '
                    """, returnStdout: true).trim()

                    println "TARGET_STACK: $targetStack"
                }
            }
        }
        stage('Build and Deploy') {
            steps {
                script {
                    if (!(params.DEPLOY_GATEWAY || params.DEPLOY_OPERATIONS || params.DEPLOY_QUERY)) {
                        error 'Nothing selected: enable at least one of DEPLOY_GATEWAY / DEPLOY_OPERATIONS / DEPLOY_QUERY.'
                    }

                    if (params.git_hash == '') {
                        def result = build job: 'Retrieve Build Spec'
                        retrieveBuildSpecId = result.number

                        copyArtifacts filter: '*', projectName: 'Retrieve Build Spec', selector: specific(""+retrieveBuildSpecId)
                        sh 'cat build-spec.json'
                        sh 'cat pipeline_git_commit.txt'
                        sh 'pwd'
                        build_hashes = parseBuildHashes(readFile('build-spec.json'))
                        pipelineBuildId = readFile('pipeline_git_commit.txt').trim()
                        infrastructure_git_hash = parseInfrastructureGitHash(readFile('build-spec.json'))
                    }

                    if (params.RUN_DATABASE_MIGRATIONS) {
                        lock('shared-db') {
                            build job: 'Database Migrations', parameters: [
                                [$class: 'StringParameterValue', name: 'infrastructure_git_hash', value: infrastructure_git_hash],
                            ]
                        }
                    }

                    lock("stack-${targetStack}") {
                        // Build only the API sub-modules that are actually being deployed.
                        def apiModules = []
                        if (params.DEPLOY_GATEWAY)    { apiModules << 'services/pic-sure-gateway' }
                        if (params.DEPLOY_OPERATIONS) { apiModules << 'services/pic-sure-operations-service' }
                        if (params.DEPLOY_QUERY)      { apiModules << 'services/pic-sure-hpds-query-service' }

                        build job: 'PIC-SURE Maven Build', parameters: [
                            [$class: 'StringParameterValue', name: 'git_hash', value: params.git_hash ?: build_hashes['PSA']],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId ?: 'MANUAL_RUN'],
                            [$class: 'StringParameterValue', name: 'MODULES', value: apiModules.join(',')]
                        ]

                        def imageParams = [
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId ?: 'MANUAL_RUN']
                        ]
                        def branches = [:]
                        if (params.DEPLOY_GATEWAY)    { branches['gateway']    = { build job: 'PIC-SURE Gateway Image', parameters: imageParams } }
                        if (params.DEPLOY_OPERATIONS) { branches['operations'] = { build job: 'PIC-SURE Operations Service Image', parameters: imageParams } }
                        if (params.DEPLOY_QUERY)      { branches['query']      = { build job: 'PIC-SURE HPDS Query Service Image', parameters: imageParams } }
                        parallel branches

                        build job: 'PIC-SURE API Deploy', parameters: [
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: params.DEPLOY_GATEWAY],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: params.DEPLOY_OPERATIONS],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_QUERY', value: params.DEPLOY_QUERY]
                        ]
                    }
                }
            }
        }
    }
}
